#!/usr/bin/env python3
# ECHO fix: "All sound" off now fully stops the audio. Replaces public/echo/index.html only.
# Run:  python3 ~/Downloads/deploy_echo_soundfix.py
import base64, os, sys
REPO=os.path.expanduser("~/Desktop/Johnsen.world/johnsen-world")
dst=os.path.join(REPO,"public","echo","index.html")
if not os.path.isfile(dst): sys.exit("ECHO not found at "+dst)
open(dst,"wb").write(base64.b64decode(""))
print("updated public/echo/index.html. Commit and push in GitHub Desktop.")
